@import "@fontsource-variable/inter";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";

/* Light (faithful): a #fafafa page, white cards, deep navy (#151e3d) text, the brand violet
   #6e56cf for CTAs and link hovers, pale lavender #f6f2fd bands, hairlines #d2d2db. */
:root {
  --background: #fafafa;
  --foreground: #151e3d;
  --card: #ffffff;
  --card-foreground: #151e3d;
  --popover: #ffffff;
  --popover-foreground: #151e3d;
  --primary: #6e56cf;
  --primary-foreground: #ffffff;
  --secondary: #f6f2fd;
  --secondary-foreground: #151e3d;
  --muted: #eeeef2;
  --muted-foreground: #5c5c78;
  --accent: #f6f2fd;
  --accent-foreground: #5643b8;
  --destructive: #d9364b;
  --destructive-foreground: #ffffff;
  --border: #d2d2db;
  --input: #b1b1be;
  --ring: #6e56cf;
  --highlight: #7fae1c;
  --highlight-foreground: #151e3d;
  --glow: #8a78db;
  --chart-1: #6e56cf;
  --chart-2: #2877f9;
  --chart-3: #17634e;
  --chart-4: #a1ded2;
  --chart-5: #cfeffc;
  --sidebar: #ffffff;
  --sidebar-foreground: #151e3d;
  --sidebar-primary: #6e56cf;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f6f2fd;
  --sidebar-accent-foreground: #151e3d;
  --sidebar-border: #d2d2db;
  --sidebar-ring: #6e56cf;

  --typeface-body: "Inter Variable", Inter, Arial, sans-serif;
  --typeface-display: "Inter Variable", Inter, Arial, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 80rem;
  --page-gutter: 1rem;
  --section-y: 7.5rem;
}

/* Dark: the navy of the testimonial band and footer (#151e3d), ink-violet cards (#1a1238)
   as on the case studies, white text, the same violet, lime code strings. */
.dark {
  --background: #151e3d;
  --foreground: #fafafa;
  --card: #1a1238;
  --card-foreground: #ffffff;
  --popover: #1e2a55;
  --popover-foreground: #ffffff;
  --primary: #6e56cf;
  --primary-foreground: #ffffff;
  --secondary: #1e2a55;
  --secondary-foreground: #ffffff;
  --muted: #232f5c;
  --muted-foreground: #8b8b9c;
  --accent: #262a63;
  --accent-foreground: #dcc6e0;
  --destructive: #ef5a6f;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 16%);
  --input: rgb(255 255 255 / 45%);
  --ring: #8a78db;
  --highlight: #abe338;
  --highlight-foreground: #151e3d;
  --glow: #8a78db;
  --chart-1: #8a78db;
  --chart-2: #2877f9;
  --chart-3: #2c9a78;
  --chart-4: #a1ded2;
  --chart-5: #cfeffc;
  --sidebar: #1a1238;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #6e56cf;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #262a63;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 16%);
  --sidebar-ring: #8a78db;
}
